import React from 'react';
import { Compass, Award } from 'lucide-react';

const AboutContent = ({ companyInfo }) => {
  return (
    <div className="lg:col-span-2">
      <div className="flex items-start mb-8">
        <Compass className="w-12 h-12 text-[#5dade2] mr-4 flex-shrink-0" />
        <div className="flex-grow">
          <h3 className="text-2xl font-light text-gray-800">About Krupa Nidhi Ropes</h3>
          <div className="flex items-center mt-2 space-x-2">
            <Award className="w-5 h-5 text-[#5dade2]" />
            <span className="text-sm font-semibold text-[#5dade2]">ISO CERTIFIED COMPANY</span>
          </div>
        </div>
      </div>
      
      <div className="space-y-6 text-gray-600 leading-relaxed">
        <p>{companyInfo.description}</p>
        <p>{companyInfo.description2}</p>
      </div>
    </div>
  );
};

export default AboutContent;
